/* ============ VOXELCRAFT UI ============ */
:root{
  --ink:#eaf2e6;
  --muted:#a9bbae;
  --panel:rgba(10,18,14,.82);
  --panel-2:rgba(16,27,21,.94);
  --line:rgba(190,235,190,.16);
  --green:#7dd35a;
  --green-deep:#3e8f36;
  --gold:#ffd479;
  --danger:#ff7676;
  --shadow:0 22px 60px rgba(0,0,0,.55);
  --safe-top:env(safe-area-inset-top,0px);
  --safe-bot:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
  --font:"Trebuchet MS","Segoe UI",system-ui,-apple-system,sans-serif;
  --mono:ui-monospace,"SFMono-Regular","Cascadia Mono","Roboto Mono",monospace;
}
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
html,body{height:100%;overflow:hidden;background:#0a120e;color:var(--ink);font-family:var(--font)}
body{overscroll-behavior:none;touch-action:none;user-select:none;-webkit-user-select:none}
canvas{display:block}
button{font-family:inherit;color:inherit;border:0;background:none;cursor:pointer}
button:focus-visible{outline:2px solid var(--green);outline-offset:3px}
.hidden{display:none!important}
.icon{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}

#app{position:fixed;inset:0;overflow:hidden;isolation:isolate;background:#0a120e}
#game{position:absolute;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}
body.is-menu #game{cursor:default;filter:saturate(1.02)}

#vignette{position:absolute;inset:0;pointer-events:none;z-index:3;
  background:radial-gradient(ellipse at 50% 46%,transparent 48%,rgba(0,0,0,.18) 78%,rgba(0,0,0,.42) 100%)}
#underwater{position:absolute;inset:0;pointer-events:none;z-index:4;opacity:0;transition:opacity .35s;
  background:linear-gradient(180deg,rgba(12,71,99,.42),rgba(4,37,58,.6));
  box-shadow:inset 0 0 140px rgba(0,35,60,.75)}
#underwater.on{opacity:1}
#hurt-flash{position:absolute;inset:0;pointer-events:none;z-index:4;background:radial-gradient(ellipse,transparent 40%,rgba(160,0,0,.55));opacity:0;transition:opacity .4s}

/* ============ HUD ============ */
#hud{position:absolute;inset:0;z-index:5;pointer-events:none}
.hud-chip{position:absolute;display:flex;align-items:center;gap:7px;height:30px;padding:0 11px;border-radius:9px;
  background:rgba(8,14,11,.5);border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(8px);
  font-family:var(--mono);font-size:11.5px;letter-spacing:.04em;color:#d8e6d8;opacity:.9}
#stats{top:calc(10px + var(--safe-top));left:calc(10px + var(--safe-l))}
#stats .dot{opacity:.35}
#clock-chip{top:calc(10px + var(--safe-top));right:calc(10px + var(--safe-r));gap:8px}
#clock-chip .moon-icon{display:none}
body.night #clock-chip .sun-icon{display:none}
body.night #clock-chip .moon-icon{display:block}
.chip-btn{pointer-events:auto;display:grid;place-items:center;width:22px;height:22px;border-radius:6px;color:#cfe0cf}
.chip-btn:hover{background:rgba(255,255,255,.1)}
.chip-btn.muted .sound-wave{display:none}
.chip-btn:not(.muted) .sound-mute{display:none}

#crosshair{position:absolute;left:50%;top:50%;width:22px;height:22px;transform:translate(-50%,-50%);opacity:.9;mix-blend-mode:difference}
#crosshair span{position:absolute;background:#fff;border-radius:1px}
.ch-h{left:0;top:10px;width:22px;height:2px}
.ch-v{left:10px;top:0;width:2px;height:22px}

#break-ring{position:absolute;left:50%;top:50%;width:44px;height:44px;transform:translate(-50%,-50%);opacity:0;transition:opacity .1s}
#break-ring.on{opacity:1}
#break-ring-fill{position:absolute;inset:0;border-radius:50%;
  background:conic-gradient(rgba(255,255,255,.92) calc(var(--p,0)*1%),rgba(255,255,255,.1) 0);
  mask:radial-gradient(circle,transparent 58%,#000 60%);-webkit-mask:radial-gradient(circle,transparent 58%,#000 60%)}

#block-label{position:absolute;left:50%;top:calc(50% + 30px);transform:translateX(-50%);font-size:11px;letter-spacing:.14em;
  text-transform:uppercase;color:rgba(255,255,255,.7);text-shadow:0 1px 4px #000;opacity:0;transition:opacity .25s;white-space:nowrap}
#block-label.on{opacity:1}

#hotbar-wrap{position:absolute;left:50%;bottom:calc(14px + var(--safe-bot));transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:10px;pointer-events:auto}
#hotbar{display:flex;gap:5px;padding:5px;border-radius:13px;background:rgba(7,13,10,.62);
  border:1px solid rgba(255,255,255,.12);backdrop-filter:blur(10px);box-shadow:0 12px 30px rgba(0,0,0,.4)}
.slot{position:relative;width:46px;height:46px;border-radius:8px;background:rgba(255,255,255,.055);
  border:2px solid transparent;display:grid;place-items:center;transition:transform .12s,border-color .12s,background .12s}
.slot .icon-img{width:34px;height:34px;image-rendering:pixelated;filter:drop-shadow(0 3px 3px rgba(0,0,0,.4))}
.slot .num{position:absolute;top:1px;left:4px;font-family:var(--mono);font-size:9px;color:rgba(255,255,255,.45)}
.slot.active{border-color:rgba(255,255,255,.92);background:rgba(255,255,255,.16);transform:translateY(-3px)}
.slot.active .num{color:#fff}
.slot.flash{animation:slot-flash .3s ease}
@keyframes slot-flash{50%{background:rgba(125,211,90,.4)}}
#block-toast{height:16px;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#eaffdf;text-shadow:0 2px 6px #000;opacity:0;transition:opacity .25s}
#block-toast.on{opacity:.9}

#desktop-hints{position:absolute;left:calc(14px + var(--safe-l));bottom:calc(16px + var(--safe-bot));display:flex;flex-direction:column;gap:3px;
  font-size:10.5px;color:rgba(230,245,230,.52);text-shadow:0 1px 3px #000;letter-spacing:.02em}
#desktop-hints b{color:rgba(255,255,255,.78);font-weight:600}

.round-btn{position:absolute;display:grid;place-items:center;width:40px;height:40px;border-radius:10px;
  background:rgba(8,14,11,.55);border:1px solid rgba(255,255,255,.12);backdrop-filter:blur(8px);
  pointer-events:auto;color:#e6f2e6;transition:background .15s,transform .15s}
.round-btn:hover{background:rgba(255,255,255,.14)}
.round-btn:active{transform:scale(.94)}
.round-btn svg{width:19px;height:19px;fill:currentColor}
#menu-btn{top:calc(48px + var(--safe-top));right:calc(10px + var(--safe-r));display:none}
#inv-btn{top:calc(48px + var(--safe-top));right:calc(56px + var(--safe-r));display:none}
body.touch #menu-btn{display:grid}
body.touch #inv-btn{display:grid}
body.touch #desktop-hints{display:none}

/* ============ TOUCH ============ */
#touch-ui{position:absolute;inset:0;z-index:6;pointer-events:none}
body:not(.touch) #touch-ui{display:none!important}
#joystick{position:absolute;left:calc(22px + var(--safe-l));bottom:calc(24px + var(--safe-bot));width:132px;height:132px;border-radius:50%;
  background:radial-gradient(circle,rgba(255,255,255,.08),rgba(0,0,0,.18));border:1.5px solid rgba(255,255,255,.22);
  backdrop-filter:blur(4px);pointer-events:auto;touch-action:none}
#joystick::after{content:"";position:absolute;inset:26%;border-radius:50%;border:1px dashed rgba(255,255,255,.15)}
#joystick-knob{position:absolute;left:50%;top:50%;width:54px;height:54px;border-radius:50%;transform:translate(-50%,-50%);
  background:rgba(235,250,235,.75);border:2px solid rgba(255,255,255,.9);box-shadow:0 6px 18px rgba(0,0,0,.35);transition:background .15s}
#joystick.active #joystick-knob{background:rgba(160,235,120,.9)}
#touch-actions{position:absolute;right:calc(16px + var(--safe-r));bottom:calc(20px + var(--safe-bot));display:flex;gap:10px;align-items:flex-end;pointer-events:none}
.touch-col{display:flex;flex-direction:column;gap:10px;align-items:center}
.touch-btn{pointer-events:auto;touch-action:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;
  width:64px;height:64px;border-radius:50%;background:rgba(14,24,18,.6);border:1.5px solid rgba(255,255,255,.24);
  color:#f0f8ee;backdrop-filter:blur(6px);box-shadow:0 8px 20px rgba(0,0,0,.3);transition:transform .08s,background .12s}
.touch-btn svg{width:27px;height:27px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.touch-btn span{font-size:8.5px;letter-spacing:.06em;text-transform:uppercase;opacity:.8}
.touch-btn.small{width:52px;height:52px}
.touch-btn.small svg{width:22px;height:22px}
.touch-btn.action{width:72px;height:72px;background:rgba(30,54,35,.62)}
.touch-btn.action svg{width:31px;height:31px}
.touch-btn.mine{background:rgba(76,59,30,.65);border-color:rgba(255,214,130,.5)}
.touch-btn:active,.touch-btn.held{transform:scale(.9);background:rgba(125,211,90,.35)}
.touch-btn.small.on{background:rgba(125,211,90,.32);border-color:rgba(125,211,90,.75)}

#rotate-hint{position:absolute;left:50%;top:calc(86px + var(--safe-top));transform:translateX(-50%);z-index:8;display:flex;align-items:center;gap:10px;
  padding:8px 14px;border-radius:10px;background:rgba(8,14,11,.82);border:1px solid var(--line);font-size:11px;color:var(--muted);
  animation:rot-in .4s ease}
#rotate-hint .rotate-icon{width:18px;height:18px;border:2px solid var(--green);border-radius:5px;transform:rotate(-20deg)}
@keyframes rot-in{from{opacity:0;transform:translate(-50%,-8px)}}

/* ============ SCREENS ============ */
.screen{position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;overflow-y:auto;overflow-x:hidden}
.menu-scrim{position:absolute;inset:0;background:
  linear-gradient(90deg,rgba(5,12,9,.92) 0%,rgba(5,12,9,.78) 34%,rgba(5,12,9,.26) 62%,rgba(5,12,9,.5) 100%),
