.gen-bar{height:4px;border-radius:3px;background:rgba(255,255,255,.09);overflow:hidden}
.gen-bar>div{height:100%;width:0;border-radius:3px;background:linear-gradient(90deg,#4faa3a,#a4e87c);transition:width .25s;box-shadow:0 0 10px rgba(125,211,90,.5)}
