.seed-row{display:flex;align-items:center;gap:8px;margin:14px 0 4px}
.seed-row label{font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;color:var(--muted)}
.seed-row input{flex:1;min-width:0;height:32px;border-radius:8px;border:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.28);
  color:var(--ink);font-family:var(--mono);font-size:12.5px;padding:0 10px;letter-spacing:.06em;outline:none}
