.menu-actions{display:grid;gap:9px;margin-top:15px}
.btn{position:relative;display:flex;align-items:center;justify-content:center;gap:10px;min-height:48px;padding:0 18px;border-radius:11px;
  font-size:15px;font-weight:700;letter-spacing:.05em;transition:transform .12s,filter .12s,background .15s;border:1px solid transparent}
