import * as THREE from 'three';

const DAY_LENGTH = 600; // seconds for a full cycle

const C = (hex) => new THREE.Color(hex);
const mixColor = (a, b, t, target = new THREE.Color()) => target.copy(a).lerp(b, t);

export class Sky {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.time = 0.23;
    this.elapsed = 0;
    this.dayLength = DAY_LENGTH;

    this.zenith = new THREE.Color();
    this.horizon = new THREE.Color();
    this.sunColor = new THREE.Color();

    this.dayZenith = C('#3f86d0');
    this.dayHorizon = C('#cfe9f7');
    this.nightZenith = C('#050a18');
    this.nightHorizon = C('#0d1a2e');
    this.sunsetZenith = C('#2b3f66');
    this.sunsetHorizon = C('#ff9a5a');
    this.sunDir = new THREE.Vector3(0, 1, 0);

    this.skyMat = new THREE.ShaderMaterial({
      uniforms: {
        uZenith: { value: new THREE.Color('#3f86d0') },
        uHorizon: { value: new THREE.Color('#cfe9f7') },
        uSunColor: { value: new THREE.Color('#fff3d0') },
        uSunDir: { value: new THREE.Vector3(0, 1, 0) },
        uNight: { value: 0 },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        uniform vec3 uZenith;
        uniform vec3 uHorizon;
        uniform vec3 uSunColor;
        uniform vec3 uSunDir;
        uniform float uNight;
        varying vec3 vDir;
        void main() {
          vec3 d = normalize(vDir);
          float h = clamp(d.y, -1.0, 1.0);
          float t = pow(clamp(h, 0.0, 1.0), 0.58);
          vec3 col = mix(uHorizon, uZenith, t);
          col = mix(col, uHorizon * 0.72, smoothstep(0.0, -0.28, h));
          vec3 sd = normalize(uSunDir);
          float sun = dot(d, sd);
          float disc = smoothstep(0.99915, 0.99975, sun);
          float glow = pow(max(sun, 0.0), 60.0) * 0.42 + pow(max(sun, 0.0), 7.0) * 0.1;
          col += uSunColor * (disc * 2.4 + glow);
          float moon = dot(d, -sd);
          float moonDisc = smoothstep(0.99935, 0.99985, moon);
          col += vec3(0.82, 0.88, 1.0) * moonDisc * (0.55 + 0.55 * uNight);
          gl_FragColor = vec4(col, 1.0);
        }`,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(450, 32, 20), this.skyMat);
    this.sky.renderOrder = -100;
    this.sky.frustumCulled = false;
    scene.add(this.sky);

    // stars
    const starCount = 900;
    const positions = new Float32Array(starCount * 3);
    const sizes = new Float32Array(starCount);
    for (let i = 0; i < starCount; i++) {
      const u = Math.random() * Math.PI * 2;
      const v = 0.04 + Math.random() * 0.96;
      const r = Math.sqrt(1 - v * v);
      positions[i * 3] = Math.cos(u) * r * 380;
      positions[i * 3 + 1] = v * 380;
      positions[i * 3 + 2] = Math.sin(u) * r * 380;
      sizes[i] = 1 + Math.random() * 2;
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    this.starMat = new THREE.PointsMaterial({
      color: 0xdfe8ff, size: 1.7, sizeAttenuation: false, transparent: true,
      opacity: 0, depthWrite: false, fog: false,
    });
    this.stars = new THREE.Points(starGeo, this.starMat);
    this.stars.renderOrder = -90;
    this.stars.frustumCulled = false;
    scene.add(this.stars);

    // clouds
    const cloudCount = 150;
    const cloudGeo = new THREE.BoxGeometry(1, 1, 1);
    this.cloudMat = new THREE.MeshBasicMaterial({
      color: 0xffffff, transparent: true, opacity: 0.78, depthWrite: false, fog: true,
    });
    this.clouds = new THREE.InstancedMesh(cloudGeo, this.cloudMat, cloudCount);
    this.clouds.instanceMatrix.setUsage(THREE.StaticDrawUsage);
    const mat = new THREE.Matrix4();
    const rand = mulberry(4242);
    for (let i = 0; i < cloudCount; i++) {
      const angle = rand() * Math.PI * 2;
      const radius = 25 + Math.sqrt(rand()) * 260;
      const x = Math.cos(angle) * radius;
      const z = Math.sin(angle) * radius;
      const y = 88 + rand() * 18;
      const w = 7 + rand() * 26;
      const d = 5 + rand() * 18;
      const h = 1.6 + rand() * 2.6;
      mat.compose(
        new THREE.Vector3(x, y, z),
        new THREE.Quaternion().setFromEuler(new THREE.Euler(0, rand() * 0.4, 0)),
        new THREE.Vector3(w, h, d),
      );
      this.clouds.setMatrixAt(i, mat);
    }
    this.clouds.instanceMatrix.needsUpdate = true;
    this.clouds.frustumCulled = false;
    this.clouds.renderOrder = -20;
    scene.add(this.clouds);

    // lights
    this.hemi = new THREE.HemisphereLight(0xcfe6ff, 0x48563a, 0.9);
    scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight(0xfff3d6, 2.0);
    this.sun.position.set(60, 120, 40);
    scene.add(this.sun);
    this.moon = new THREE.DirectionalLight(0x93a9e8, 0.0);
    this.moon.position.set(-60, 80, -40);
    scene.add(this.moon);

    this.fog = new THREE.Fog(0xcfe9f7, 80, 150);
    scene.fog = this.fog;
    this.fogFar = 150;

    this.update(0, null);
  }

  get hours() {
    const h = (6 + ((this.time % 1) + 1) % 1 * 24) % 24;
    return h;
  }

  get clockString() {
    const h = this.hours;
    const hh = Math.floor(h).toString().padStart(2, '0');
    const mm = Math.floor((h % 1) * 60).toString().padStart(2, '0');
    return `${hh}:${mm}`;
  }

  setFogDistance(far) {
    this.fogFar = far;
    this.fog.near = far * 0.45;
    this.fog.far = far;
  }

  update(dt, camera) {
    this.elapsed += dt;
    this.time = (this.time + dt / this.dayLength) % 1;
    const t = this.time;
    const ang = t * Math.PI * 2;
    this.sunDir.set(Math.cos(ang) * 0.92, Math.sin(ang), 0.42).normalize();
    const elev = this.sunDir.y;
    const day = smoothThree(-0.08, 0.22, elev);
    const sunset = Math.exp(-Math.pow(elev / 0.17, 2)) * smoothThree(-0.35, -0.05, elev);
    const night = 1 - day;

    mixColor(this.nightZenith, this.dayZenith, day, this.zenith);
    this.zenith.lerp(this.sunsetZenith, sunset * 0.5);
    mixColor(this.nightHorizon, this.dayHorizon, day, this.horizon);
    this.horizon.lerp(this.sunsetHorizon, sunset * 0.8);
    mixColor(new THREE.Color('#ff6b30'), new THREE.Color('#fff4d6'), smoothThree(0.0, 0.3, elev), this.sunColor);

    this.skyMat.uniforms.uZenith.value.copy(this.zenith);
    this.skyMat.uniforms.uHorizon.value.copy(this.horizon);
    this.skyMat.uniforms.uSunColor.value.copy(this.sunColor);
    this.skyMat.uniforms.uSunDir.value.copy(this.sunDir);
    this.skyMat.uniforms.uNight.value = night;

    this.fog.color.copy(this.horizon);
    this.starMat.opacity = Math.pow(night, 1.4) * 0.95;
    this.stars.rotation.y = this.elapsed * 0.008;

    this.cloudMat.opacity = 0.55 + day * 0.25;
    this.cloudMat.color.copy(this.horizon).lerp(new THREE.Color('#ffffff'), 0.45 + day * 0.4);
    this.clouds.position.x = Math.sin(this.elapsed * 0.006) * 30;
    this.clouds.position.z = this.elapsed * 0.6 % 80;

    this.hemi.intensity = 0.24 + day * 0.72;
    this.hemi.color.copy(this.horizon).lerp(new THREE.Color('#bfe0ff'), 0.5);
    this.hemi.groundColor.setHex(0x3d4a32).lerp(new THREE.Color('#1a2018'), night);
    this.sun.intensity = Math.max(0, day) * 2.05;
    this.sun.color.copy(this.sunColor);
    this.sun.position.copy(this.sunDir).multiplyScalar(180);
    this.moon.intensity = Math.max(0, -elev) * 0.5;
    this.moon.position.copy(this.sunDir).multiplyScalar(-180);

    if (camera) {
      this.sky.position.copy(camera.position);
      this.stars.position.copy(camera.position);
    }
  }
}

function smoothThree(a, b, x) {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

function mulberry(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

import * as THREE from 'three';

export function createMaterials(atlas) {
  const solid = new THREE.MeshLambertMaterial({
    map: atlas,
    vertexColors: true,
    alphaTest: 0.3,
    side: THREE.FrontSide,
  });

  const plant = new THREE.MeshLambertMaterial({
    map: atlas,
    vertexColors: true,
    alphaTest: 0.35,
    side: THREE.DoubleSide,
  });

  const glass = new THREE.MeshLambertMaterial({
    map: atlas,
    vertexColors: true,
    transparent: true,
    opacity: 0.95,
    depthWrite: false,
    side: THREE.FrontSide,
  });

  const water = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uSunDir: { value: new THREE.Vector3(0.5, 0.8, 0.2) },
      uSunColor: { value: new THREE.Color('#fff0c8') },
      uDay: { value: 1 },
      uFogColor: { value: new THREE.Color('#cfe9f7') },
      uFogNear: { value: 60 },
      uFogFar: { value: 150 },
    },
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorld;
      varying vec3 vNrm;
      void main() {
        vec3 p = position;
        if (normal.y > 0.5) {
          p.y += sin(p.x * 0.55 + uTime * 1.15) * 0.045
               + sin(p.z * 0.7 - uTime * 0.9) * 0.035
               + sin((p.x + p.z) * 0.22 + uTime * 0.5) * 0.025;
        }
        vWorld = p;
        vNrm = normalize(normalMatrix * normal);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
      }`,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uSunColor;
      uniform float uDay;
      uniform vec3 uFogColor;
      uniform float uFogNear;
      uniform float uFogFar;
      varying vec3 vWorld;
      varying vec3 vNrm;
      void main() {
        vec3 viewDir = normalize(cameraPosition - vWorld);
        float w1 = sin(vWorld.x * 0.35 + uTime * 0.8);
        float w2 = cos(vWorld.z * 0.42 - uTime * 0.65);
        vec3 n = normalize(vec3(w1 * 0.075, 1.0, w2 * 0.075));
        if (abs(vNrm.y) < 0.5) n = normalize(vNrm);
        float fres = pow(1.0 - max(dot(viewDir, n), 0.0), 2.2);
        vec3 deep = vec3(0.022, 0.145, 0.26) * (0.32 + uDay * 0.68);
        vec3 shallow = vec3(0.075, 0.36, 0.5) * (0.3 + uDay * 0.7);
        vec3 col = mix(deep, shallow, fres * 0.85 + 0.08);
        vec3 sunDir = normalize(uSunDir);
        float spec = pow(max(dot(reflect(-sunDir, n), viewDir), 0.0), 110.0);
        col += uSunColor * spec * (0.45 + uDay * 1.15);
        float horizon = pow(max(dot(viewDir, vec3(0.0, 1.0, 0.0)), 0.0), 3.0);
        col += vec3(0.05, 0.1, 0.12) * horizon * uDay;
        float fogF = smoothstep(uFogNear, uFogFar, length(cameraPosition - vWorld));
        col = mix(col, uFogColor, fogF);
        float alpha = mix(0.64, 0.9, fres);
        gl_FragColor = vec4(col, alpha);
      }`,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  return { solid, plant, glass, water };
}

export function updateWaterMaterial(material, time, sky) {
  const u = material.uniforms;
  u.uTime.value = time;
  u.uSunDir.value.copy(sky.sunDir);
  u.uSunColor.value.copy(sky.sunColor);
  u.uDay.value = Math.max(0.12, Math.min(1, sky.sunDir.y * 3 + 0.35));
  u.uFogColor.value.copy(sky.fog.color);
  u.uFogNear.value = sky.fog.near;
  u.uFogFar.value = sky.fog.far;
}

// Tiny procedural sound engine - no assets needed.
export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.volume = 0.7;
    this.muted = false;
    this.enabled = false;
    this.noise = null;
    this.nextChirp = 4;
    this.day = 1;
  }

  enable() {
    if (this.enabled) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : this.volume;
      this.master.connect(this.ctx.destination);
      this.noise = this.makeNoise(1.5);
      this.enabled = true;
      this.startWind();
      if (this.ctx.state === 'suspended') this.ctx.resume();
    } catch { /* audio is a nice-to-have */ }
  }

  makeNoise(seconds) {
    const rate = this.ctx.sampleRate;
    const buffer = this.ctx.createBuffer(1, rate * seconds, rate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setVolume(v) {
    this.volume = v;
    if (this.master && !this.muted) this.master.gain.value = v;
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : this.volume;
  }

  startWind() {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.035;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    this.windGain = gain;
  }

  update(dt, sky) {
    if (!this.enabled) return;
    this.day = Math.max(0, Math.min(1, sky.sunDir.y * 3 + 0.3));
    if (this.windGain) {
      this.windGain.gain.value = 0.022 + this.day * 0.02;
    }
    this.nextChirp -= dt;
    if (this.nextChirp <= 0) {
      this.nextChirp = 6 + Math.random() * 12;
      if (this.day > 0.4) this.chirp();
    }
  }

  burst({ freq = 800, q = 0.8, dur = 0.12, gain = 0.18, type = 'bandpass', slide = 0 }) {
    if (!this.enabled || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    if (slide) f.frequency.exponentialRampToValueAtTime(Math.max(80, freq + slide), t + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t, Math.random() * 0.9, dur + 0.02);
    src.stop(t + dur + 0.05);
  }

  tone({ freq = 440, dur = 0.14, gain = 0.12, type = 'sine', slide = 0 }) {
    if (!this.enabled || this.muted) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(60, freq + slide), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  step(blockSound = 'grass') {
    const map = {
      grass: [900, 0.12, 0.1], dirt: [620, 0.12, 0.13], stone: [1500, 0.15, 0.11],
      sand: [1900, 0.1, 0.08], wood: [700, 0.14, 0.12], leaves: [1200, 0.12, 0.07],
      snow: [1100, 0.1, 0.07], gravel: [800, 0.14, 0.12], glass: [2200, 0.16, 0.07],
      plant: [1000, 0.1, 0.05], water: [500, 0.2, 0.12],
    };
    const [freq, dur, gain] = map[blockSound] || map.grass;
    this.burst({ freq, dur, gain, q: 1.1, slide: -freq * 0.35 });
  }

  dig(blockSound = 'stone') {
    const freq = blockSound === 'stone' ? 1800 : blockSound === 'wood' ? 900 : 1300;
    this.burst({ freq, dur: 0.055, gain: 0.06, q: 1.4, slide: -300 });
  }

  breakBlock(blockSound = 'stone') {
    const freq = blockSound === 'stone' ? 900 : blockSound === 'wood' ? 600 : 1100;
    this.burst({ freq, dur: 0.24, gain: 0.16, q: 0.7, slide: -freq * 0.55 });
    this.tone({ freq: 130, dur: 0.12, gain: 0.05, type: 'sine', slide: -50 });
  }

  place(blockSound = 'stone') {
    const freq = blockSound === 'wood' ? 520 : 780;
    this.burst({ freq, dur: 0.09, gain: 0.12, q: 0.9, slide: -200 });
    this.tone({ freq: 160, dur: 0.08, gain: 0.04, type: 'sine', slide: -40 });
  }

  splash() {
    this.burst({ freq: 700, dur: 0.38, gain: 0.12, q: 0.6, slide: -450, type: 'lowpass' });
  }

  jump() {
    this.burst({ freq: 480, dur: 0.1, gain: 0.045, q: 0.8, slide: 120 });
  }

  ui() {
    this.tone({ freq: 660, dur: 0.06, gain: 0.05, type: 'triangle' });
  }

  chirp() {
    const base = 1500 + Math.random() * 900;
    this.tone({ freq: base, dur: 0.09, gain: 0.025, type: 'sine', slide: 500 });
    setTimeout(() => this.tone({ freq: base + 260, dur: 0.08, gain: 0.02, type: 'sine', slide: -350 }), 120);
  }
}

import * as THREE from 'three';

const MAX = 480;

export class Particles {
  constructor(scene) {
    const geo = new THREE.BoxGeometry(1, 1, 1);
    const mat = new THREE.MeshLambertMaterial({ color: 0xffffff });
    this.mesh = new THREE.InstancedMesh(geo, mat, MAX);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.castShadow = false;
    this.mesh.receiveShadow = false;
    scene.add(this.mesh);
    this.items = [];
    const zero = new THREE.Matrix4().makeScale(0, 0, 0);
    for (let i = 0; i < MAX; i++) {
      this.items.push({ life: 0, maxLife: 1, pos: new THREE.Vector3(), vel: new THREE.Vector3(), size: 0.1, rot: new THREE.Euler(), spin: new THREE.Vector3(), color: new THREE.Color() });
      this.mesh.setMatrixAt(i, zero);
      this.mesh.setColorAt(i, new THREE.Color(1, 1, 1));
    }
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
    this.cursor = 0;
    this.dummy = new THREE.Object3D();
  }

  burst(pos, color, count = 12, spread = 2.6, size = 0.11, life = 0.9) {
    for (let i = 0; i < count; i++) {
      const p = this.items[this.cursor];
      const idx = this.cursor;
      this.cursor = (this.cursor + 1) % MAX;
      p.life = p.maxLife = life * (0.55 + Math.random() * 0.7);
      p.pos.set(pos.x + (Math.random() - 0.5) * 0.7, pos.y + (Math.random() - 0.5) * 0.7, pos.z + (Math.random() - 0.5) * 0.7);
      p.vel.set((Math.random() - 0.5) * spread, Math.random() * spread * 0.9 + 1, (Math.random() - 0.5) * spread);
      p.size = size * (0.6 + Math.random() * 0.9);
      p.rot.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
      p.spin.set((Math.random() - 0.5) * 9, (Math.random() - 0.5) * 9, (Math.random() - 0.5) * 9);
      p.color.setRGB(color[0], color[1], color[2]);
      this.mesh.setColorAt(idx, p.color);
    }
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  update(dt) {
    const dummy = this.dummy;
    let changed = false;
    for (let i = 0; i < MAX; i++) {
      const p = this.items[i];
      if (p.life <= 0) continue;
      p.life -= dt;
      if (p.life <= 0) {
        dummy.position.set(0, -999, 0);
        dummy.scale.setScalar(0);
        dummy.updateMatrix();
        this.mesh.setMatrixAt(i, dummy.matrix);
        changed = true;
        continue;
      }
      p.vel.y -= 22 * dt;
      p.vel.x *= 0.995;
      p.vel.z *= 0.995;
      p.pos.addScaledVector(p.vel, dt);
      p.rot.x += p.spin.x * dt;
      p.rot.y += p.spin.y * dt;
      p.rot.z += p.spin.z * dt;
      const fade = Math.min(1, p.life / (p.maxLife * 0.35));
      dummy.position.copy(p.pos);
      dummy.rotation.copy(p.rot);
      dummy.scale.setScalar(p.size * fade);
      dummy.updateMatrix();
      this.mesh.setMatrixAt(i, dummy.matrix);
      changed = true;
    }
    if (changed) this.mesh.instanceMatrix.needsUpdate = true;
  }
}

import { BLOCKS, INVENTORY_BLOCKS, DEFAULT_HOTBAR, faceTile } from './blocks.js';
import { blockIcon } from './textures.js';

const SETTINGS_KEY = 'voxelcraft.settings.v1';
export const DEFAULT_SETTINGS = {
  sensitivity: 1,
  volume: 0.7,
  fog: 150,
  showStats: true,
  invertY: false,
};

export function loadSettings() {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) };
  } catch { /* ignore */ }
  return { ...DEFAULT_SETTINGS };
}

export function saveSettings(settings) {
  try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch { /* ignore */ }
}

export class UI {
  constructor({ atlasCanvas, hotbar, callbacks }) {
    this.atlasCanvas = atlasCanvas;
    this.hotbar = hotbar.slice(0, 9);
    this.selected = 0;
    this.callbacks = callbacks;
    this.settings = loadSettings();
    this.touch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    if (this.touch) document.body.classList.add('touch');
    this.screens = {
      menu: document.getElementById('menu'),
      loading: document.getElementById('loading'),
      pause: document.getElementById('pause'),
      settings: document.getElementById('settings'),
      inventory: document.getElementById('inventory'),
    };
    this.hud = document.getElementById('hud');
    this.hotbarEl = document.getElementById('hotbar');
    this.invGrid = document.getElementById('inv-grid');
    this.toastEl = null;
    this.blockToastEl = document.getElementById('block-toast');
    this.breakRing = document.getElementById('break-ring');
    this.breakFill = document.getElementById('break-ring-fill');
    this.lastToast = 0;
    this.buildHotbar();
    this.buildInventory();
    this.bindSettings();
    this.bindButtons();
    this.setSettings(this.settings);
    this.touchControls = {
      joystick: document.getElementById('joystick'),
      knob: document.getElementById('joystick-knob'),
      fly: document.getElementById('t-fly'),
      jump: document.getElementById('t-jump'),
      mine: document.getElementById('t-mine'),
      place: document.getElementById('t-place'),
    };
    this.touchUI = document.getElementById('touch-ui');
  }

  get selectedBlock() { return this.hotbar[this.selected]; }
  get isTouch() { return this.touch; }

  buildHotbar() {
    this.hotbarEl.innerHTML = '';
    this.hotbar.forEach((id, i) => {
      const slot = document.createElement('button');
      slot.className = 'slot' + (i === this.selected ? ' active' : '');
      slot.dataset.index = i;
      slot.setAttribute('aria-label', `${i + 1}: ${BLOCKS[id].name}`);
      slot.innerHTML = `<span class="num">${i + 1}</span><img class="icon-img" alt="" draggable="false">`;
      slot.querySelector('img').src = blockIcon(id, this.atlasCanvas, 64);
      slot.addEventListener('click', (e) => {
        e.stopPropagation();
        this.selectSlot(i);
      });
      this.hotbarEl.appendChild(slot);
    });
  }

  updateHotbar() {
    [...this.hotbarEl.children].forEach((slot, i) => {
      slot.classList.toggle('active', i === this.selected);
      slot.setAttribute('aria-label', `${i + 1}: ${BLOCKS[this.hotbar[i]].name}`);
      slot.querySelector('img').src = blockIcon(this.hotbar[i], this.atlasCanvas, 64);
    });
    document.getElementById('inv-slot-num').textContent = this.selected + 1;
  }

  selectSlot(i) {
    if (i < 0 || i >= this.hotbar.length) return;
    this.selected = i;
    this.updateHotbar();
    this.showBlockToast(BLOCKS[this.hotbar[i]].name);
    this.callbacks.onSlot?.(i);
  }

  setSlotBlock(id) {
    this.hotbar[this.selected] = id;
    this.updateHotbar();
    this.showBlockToast(BLOCKS[id].name);
    const el = this.hotbarEl.children[this.selected];
    el.classList.remove('flash');
    void el.offsetWidth;
    el.classList.add('flash');
    this.callbacks.onHotbarChange?.(this.hotbar);
  }

  showBlockToast(name) {
    if (!this.blockToastEl) return;
    this.blockToastEl.textContent = name;
    this.blockToastEl.classList.add('on');
    clearTimeout(this.blockToastTimer);
    this.blockToastTimer = setTimeout(() => this.blockToastEl.classList.remove('on'), 1400);
  }

  buildInventory() {
    this.invGrid.innerHTML = '';
    INVENTORY_BLOCKS.forEach((id) => {
      const b = BLOCKS[id];
      const btn = document.createElement('button');
      btn.className = 'inv-item';
      btn.title = b.name;
      const img = document.createElement('img');
      img.src = blockIcon(id, this.atlasCanvas, 64);
      img.alt = b.name;
      img.draggable = false;
      const label = document.createElement('span');
      label.textContent = b.name;
      btn.append(img, label);
      btn.addEventListener('click', () => {
        this.setSlotBlock(id);
        this.callbacks.onInventoryPick?.(id);
        this.hideInventory();
      });
      this.invGrid.appendChild(btn);
    });
  }

  bindSettings() {
    const sens = document.getElementById('set-sens');
    const vol = document.getElementById('set-vol');
    const fog = document.getElementById('set-fog');
    const fps = document.getElementById('set-fps');
    const inv = document.getElementById('set-invert');
    sens.value = this.settings.sensitivity;
    vol.value = this.settings.volume;
    fog.value = this.settings.fog;
    fps.checked = this.settings.showStats;
    inv.checked = this.settings.invertY;
    document.getElementById('out-sens').textContent = Number(this.settings.sensitivity).toFixed(1);
    document.getElementById('out-vol').textContent = `${Math.round(this.settings.volume * 100)}%`;
    document.getElementById('out-fog').textContent = this.settings.fog;

    sens.addEventListener('input', () => {
      this.settings.sensitivity = Number(sens.value);
      document.getElementById('out-sens').textContent = this.settings.sensitivity.toFixed(1);
      this.emitSettings();
    });
    vol.addEventListener('input', () => {
      this.settings.volume = Number(vol.value);
      document.getElementById('out-vol').textContent = `${Math.round(this.settings.volume * 100)}%`;
      this.emitSettings();
    });
    fog.addEventListener('input', () => {
      this.settings.fog = Number(fog.value);
      document.getElementById('out-fog').textContent = this.settings.fog;
      this.emitSettings();
    });
    fps.addEventListener('change', () => {
      this.settings.showStats = fps.checked;
      this.emitSettings();
    });
    inv.addEventListener('change', () => {
      this.settings.invertY = inv.checked;
      this.emitSettings();
    });
  }

  emitSettings() {
    saveSettings(this.settings);
    this.callbacks.onSettings?.(this.settings);
  }

  setSettings(settings) {
    this.settings = settings;
    const stats = document.getElementById('stats');
    if (stats) stats.style.display = settings.showStats ? '' : 'none';
    this.callbacks.onSettings?.(settings);
  }

  bindButtons() {
    const on = (id, fn) => document.getElementById(id)?.addEventListener('click', (e) => { e.stopPropagation(); fn(e); });
    on('play-btn', () => this.callbacks.onPlay?.());
    on('new-btn', () => this.callbacks.onNewWorld?.());
    on('seed-rand', () => {
      document.getElementById('seed-input').value = String(Math.floor(Math.random() * 900000) + 100000);
      this.callbacks.onUiSound?.();
    });
    on('resume-btn', () => this.callbacks.onResume?.());
    on('pause-settings-btn', () => this.openSettings());
    on('pause-inv-btn', () => { this.hidePause(); this.showInventory(); });
    on('pause-new-btn', () => this.callbacks.onNewWorld?.());
    on('pause-menu-btn', () => this.callbacks.onMainMenu?.());
    on('settings-close', () => this.closeSettings());
    on('menu-btn', () => this.callbacks.onPause?.());
    on('inv-btn', () => this.showInventory());
    on('inv-close', () => this.hideInventory());
    on('mute-btn', () => this.callbacks.onMute?.());
    on('t-fly', () => this.callbacks.onFly?.());
    on('t-jump', () => this.callbacks.onJump?.());
    on('t-mine', () => this.callbacks.onTouchMine?.());
    on('t-place', () => this.callbacks.onTouchPlace?.());
    document.querySelectorAll('.screen').forEach((screen) => {
      screen.addEventListener('click', (e) => {
        if (e.target === screen) {
          if (screen.id === 'settings') this.closeSettings();
          if (screen.id === 'inventory') this.hideInventory();
        }
      });
    });
  }

  setSeed(seed) {
    const input = document.getElementById('seed-input');
    if (input) input.value = String(seed);
  }

  seedValue() {
    const input = document.getElementById('seed-input');
    const n = parseInt(input?.value, 10);
    return Number.isFinite(n) ? n : 1337;
  }

  setGeneration(progress, title, sub) {
    const pct = Math.max(0, Math.min(100, Math.round(progress * 100)));
    document.getElementById('gen-fill').style.width = `${pct}%`;
    document.getElementById('gen-pct').textContent = `${pct}%`;
    if (title) document.getElementById('gen-title').textContent = title;
    if (sub) document.getElementById('gen-sub').textContent = sub;
  }

  setReady(info) {
    document.body.classList.add('world-ready');
    this.setGeneration(1, 'Світ готовий', info);
    const btn = document.getElementById('play-btn');
    btn.disabled = false;
    btn.querySelector('.btn-main').textContent = 'Грати';
    btn.querySelector('.btn-sub').textContent = info;
    this.setLoading(false);
  }

  setPlayEnabled(enabled) {
    const btn = document.getElementById('play-btn');
    if (btn) btn.disabled = !enabled;
  }

  setLoading(show, progress = 0) {
    if (show) {
      this.screens.loading.classList.remove('hidden');
      document.getElementById('load-fill').style.width = `${Math.round(progress * 100)}%`;
      document.getElementById('load-pct').textContent = `${Math.round(progress * 100)}%`;
    } else {
      this.screens.loading.classList.add('hidden');
    }
  }

  showMenu() {
    document.body.classList.add('is-menu');
    this.screens.menu.classList.remove('hidden');
    this.hud.classList.add('hidden');
    this.touchUI.classList.add('hidden');
  }

  hideMenu() {
    document.body.classList.remove('is-menu');
    this.screens.menu.classList.add('hidden');
    this.hud.classList.remove('hidden');
    if (this.touch) this.touchUI.classList.remove('hidden');
  }

  showPause() {
    this.screens.pause.classList.remove('hidden');
    document.getElementById('pause-seed').textContent = document.getElementById('seed-input').value;
    if (this.touch) this.touchUI.classList.add('hidden');
  }
  hidePause() {
    this.screens.pause.classList.add('hidden');
    if (this.touch && !document.body.classList.contains('is-menu')) this.touchUI.classList.remove('hidden');
  }
  pauseOpen() { return !this.screens.pause.classList.contains('hidden'); }

  openSettings() { this.screens.settings.classList.remove('hidden'); }
  closeSettings() { this.screens.settings.classList.add('hidden'); }
  settingsOpen() { return !this.screens.settings.classList.contains('hidden'); }

  showInventory() {
    this.screens.inventory.classList.remove('hidden');
    document.getElementById('inv-slot-num').textContent = this.selected + 1;
    this.callbacks.onInventoryOpen?.(true);
  }
  hideInventory() {
    this.screens.inventory.classList.add('hidden');
    this.callbacks.onInventoryOpen?.(false);
  }
  inventoryOpen() { return !this.screens.inventory.classList.contains('hidden'); }

  setStats(fps, x, y, z) {
    document.getElementById('stat-fps').textContent = `${fps} FPS`;
    document.getElementById('stat-pos').textContent = `${Math.round(x)} ${Math.round(y)} ${Math.round(z)}`;
  }

  setClock(text, night) {
    document.getElementById('stat-time').textContent = text;
    document.body.classList.toggle('night', night);
  }

  setMuted(muted) {
    document.getElementById('mute-btn').classList.toggle('muted', muted);
  }

  setBreakProgress(p) {
    if (p <= 0) {
      this.breakRing.classList.remove('on');
      return;
    }
    this.breakRing.classList.add('on');
    this.breakFill.style.setProperty('--p', Math.round(p * 100));
  }

  setUnderwater(on) {
    document.getElementById('underwater').classList.toggle('on', on);
  }

  toast(text, duration = 2200) {
    if (!this.toastEl) {
      const el = document.createElement('div');
      el.id = 'toast';
      document.getElementById('app').appendChild(el);
      this.toastEl = el;
    }
    this.toastEl.textContent = text;
    this.toastEl.classList.add('on');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => this.toastEl.classList.remove('on'), duration);
  }

  flashHurt() {
    const el = document.getElementById('hurt-flash');
    el.style.opacity = '1';
    clearTimeout(this.hurtTimer);
    this.hurtTimer = setTimeout(() => { el.style.opacity = '0'; }, 220);
  }

  setFlyState(flying) {
    document.getElementById('t-fly').classList.toggle('on', flying);
  }

  showRotateHint() {
    if (!this.touch) return;
    if (window.innerHeight > window.innerWidth && window.innerWidth < 700) {
      const hint = document.getElementById('rotate-hint');
      hint.classList.remove('hidden');
      clearTimeout(this.rotateTimer);
      this.rotateTimer = setTimeout(() => hint.classList.add('hidden'), 4200);
    }
  }

  updateTouchHotbarWheel() { /* reserved */ }
}

