// clouds - several overlapping puffs per cloud for a softer silhouette
const cloudCount = 210;
const cloudGeo = new THREE.BoxGeometry(1, 1, 1);
this.cloudMat = new THREE.MeshLambertMaterial({
  color: 0xffffff, transparent: true, opacity: 0.82, depthWrite: false, fog: true,
});
this.clouds = new THREE.InstancedMesh(cloudGeo, this.cloudMat, cloudCount);
this.clouds.instanceMatrix.setUsage(THREE.StaticDrawUsage);
const mat = new THREE.Matrix4();
const rand = mulberry(4242);
for (let i = 0; i < cloudCount; i++) {
  const cluster = Math.floor(i / 3);
  const lr = mulberry(9000 + cluster * 977);
  const angle = (cluster / Math.ceil(cloudCount / 3)) * Math.PI * 2 + lr() * 0.5;
  const radius = 20 + Math.sqrt(lr()) * 240;
  const bx = Math.cos(angle) * radius;
  const bz = Math.sin(angle) * radius;
  const by = 90 + lr() * 16;
  const w = 9 + lr() * 24;
  const d = 7 + lr() * 17;
  const h = 1.4 + lr() * 2.2;
  const ox = (i % 3 - 1) * w * 0.33 + (lr() - 0.5) * w * 0.4;
  const oz = (lr() - 0.5) * d * 0.6;
  mat.compose(
    new THREE.Vector3(bx + ox, by + (i % 3) * 0.35, bz + oz),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(0, lr() * 0.4, 0)),
    new THREE.Vector3(w * (0.8 + lr() * 0.35), h, d * (0.8 + lr() * 0.3)),
  );
  this.clouds.setMatrixAt(i, mat);
}

