// clouds - flat voxel puffs kept high above the island so the camera never
// flies through a grey slab; unlit so they stay soft and white
const cloudCount = 180;
const cloudGeo = new THREE.BoxGeometry(1, 1, 1);
this.cloudMat = new THREE.MeshBasicMaterial({
  color: 0xffffff, transparent: true, opacity: 0.8, depthWrite: false, fog: true,
});
this.clouds = new THREE.InstancedMesh(cloudGeo, this.cloudMat, cloudCount);
this.clouds.instanceMatrix.setUsage(THREE.StaticDrawUsage);
const mat = new THREE.Matrix4();
const rand = mulberry(4242);
for (let i = 0; i < cloudCount; i++) {
  const cluster = Math.floor(i / 3);
  const lr = mulberry(9000 + cluster * 977);
  const angle = (cluster / Math.ceil(cloudCount / 3)) * Math.PI * 2 + lr() * 0.5;
  const radius = 24 + Math.sqrt(lr()) * 260;
  const bx = Math.cos(angle) * radius;
  const bz = Math.sin(angle) * radius;
  const by = 142 + lr() * 20;
  const w = 7 + lr() * 18;
  const d = 6 + lr() * 14;
  const h = 1.1 + lr() * 1.4;
  const ox = (i % 3 - 1) * w * 0.36 + (lr() - 0.5) * w * 0.35;
  const oz = (lr() - 0.5) * d * 0.55;
  mat.compose(
    new THREE.Vector3(bx + ox, by + (i % 3) * 0.25, bz + oz),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(0, lr() * 0.5, 0)),
    new THREE.Vector3(w * (0.8 + lr() * 0.35), h, d * (0.8 + lr() * 0.3)),
  );
  this.clouds.setMatrixAt(i, mat);
}

