    const v = window.__voxelcraft;
    const r = v.heldRoot;
    const out = { pos: r.position.toArray(), rot: r.rotation.toArray(), scale: r.scale.toArray(), visible: r.visible, children: [] };
    r.children.forEach(c => {
      const b = c.geometry?.boundingBox;
      out.children.push({type:c.type, pos:c.position.toArray(), visible:c.visible, hasGeo:!!c.geometry, matType:c.material?.type, box:b?[b.min.toArray(),b.max.toArray()]:null});
    });
