  const mp = await mctx.newPage();
  mp.on('pageerror', e => log('MOBILE PAGEERROR', e.message));
  await mp.goto(URL, { waitUntil: 'load' });
  await mp.waitForFunction(() => !document.getElementById('play-btn').disabled, null, { timeout: 120000, polling: 200 });
  await mp.waitForTimeout(700);
  await mp.screenshot({ path: '/tmp/opencode/final-mobile-menu.png' });
